//! End-to-end tests of the Recovery Key commands against a real folder store: turning it on, replacing and
//! turning it off, `figlock forgot` resetting a password with it, and the negative cases (wrong credentials,
//! the old code after a replacement, a vault with no key). Codes and passwords are generated by the commands.

use std::fs;
use std::io::Write;
use std::process::{Command, Output, Stdio};

use serde_json::Value;
use tempfile::TempDir;

const PW: &str = "unit-test-password";
const NEW_PW: &str = "a-brand-new-test-password";
const SECRET: &str = "Zq9-test-secret-value-1";

fn text(b: &[u8]) -> String {
    String::from_utf8_lossy(b).into_owned()
}

struct Env {
    home: TempDir,
    store: TempDir,
    secret_key: String,
    recovery_key: Option<String>,
}

/// The value after `label` on the first line of `out` that starts with it.
fn labelled(out: &str, label: &str) -> Option<String> {
    out.lines()
        .find_map(|l| l.strip_prefix(label))
        .map(|v| v.trim().to_owned())
}

impl Env {
    fn init_with(extra: &[&str]) -> Env {
        let mut e = Env {
            home: TempDir::new().unwrap(),
            store: TempDir::new().unwrap(),
            secret_key: String::new(),
            recovery_key: None,
        };
        let store = e.store.path().to_str().unwrap().to_owned();
        let mut args = vec!["init", "--store", &store, "--kdf", "floor"];
        args.extend_from_slice(extra);
        let out = e.exec(&args, "", PW, None, &[]);
        assert!(out.status.success(), "{}", text(&out.stderr));
        let stdout = text(&out.stdout);
        e.secret_key = labelled(&stdout, "Secret Key: ").expect("secret key printed");
        e.recovery_key = labelled(&stdout, "Recovery Key: ");
        e
    }

    fn init() -> Env {
        Self::init_with(&["--no-recovery-key"])
    }

    fn exec(
        &self,
        args: &[&str],
        stdin: &str,
        pw: &str,
        sk: Option<&str>,
        envs: &[(&str, &str)],
    ) -> Output {
        let mut c = Command::new(env!("CARGO_BIN_EXE_figlock"));
        c.args(args)
            .env("FIGLOCK_HOME", self.home.path())
            .env("FIGLOCK_DEVICE_KEYS", "file")
            .env("FIGLOCK_PASSWORD", pw)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        if let Some(sk) = sk {
            c.env("FIGLOCK_SECRET_KEY", sk);
        }
        c.envs(envs.iter().copied());
        let mut child = c.spawn().unwrap();
        let _ = child.stdin.take().unwrap().write_all(stdin.as_bytes());
        child.wait_with_output().unwrap()
    }

    fn run(&self, args: &[&str]) -> Output {
        self.exec(args, "", PW, Some(&self.secret_key), &[])
    }

    fn ok(&self, args: &[&str]) -> String {
        let out = self.run(args);
        assert!(out.status.success(), "{args:?}: {}", text(&out.stderr));
        text(&out.stdout)
    }

    fn add(&self, title: &str) {
        let out = self.exec(
            &[
                "add", "--type", "login", "--title", title, "--secret", "password",
            ],
            &format!("{SECRET}\n"),
            PW,
            Some(&self.secret_key),
            &[],
        );
        assert!(out.status.success(), "{}", text(&out.stderr));
    }

    fn vault_json(&self) -> Vec<u8> {
        fs::read(self.store.path().join("vault.json")).unwrap()
    }

    fn enabled(&self) -> bool {
        let v: Value =
            serde_json::from_str(&self.ok(&["--json", "recovery-key", "status"])).unwrap();
        v["enabled"].as_bool().unwrap()
    }

    /// `figlock forgot` with `code`, resetting to [`NEW_PW`]. `more` are extra arguments.
    fn forgot(&self, code: &str, more: &[&str]) -> Output {
        let mut args = vec!["--json", "forgot", "--saved"];
        args.extend_from_slice(more);
        self.exec(
            &args,
            "",
            "unused-old-password",
            None,
            &[
                ("FIGLOCK_RECOVERY_KEY", code),
                ("FIGLOCK_NEW_PASSWORD", NEW_PW),
            ],
        )
    }

    /// Unlocks with the given credentials and lists items.
    fn find(&self, pw: &str, sk: &str) -> Output {
        self.exec(&["find"], "", pw, Some(sk), &[])
    }

    fn enable(&self) -> String {
        let out = self.ok(&["--json", "recovery-key", "enable", "--saved"]);
        let v: Value = serde_json::from_str(&out).unwrap();
        v["recovery_key"].as_str().unwrap().to_owned()
    }
}

#[test]
fn init_offers_the_recovery_key_and_prints_it_once() {
    let with = Env::init_with(&["--recovery-key"]);
    let code = with
        .recovery_key
        .clone()
        .expect("a Recovery Key is printed");
    assert!(code.starts_with("FLR1-"));
    assert!(with.enabled());

    let without = Env::init_with(&["--no-recovery-key"]);
    assert!(without.recovery_key.is_none());
    assert!(!without.enabled());

    // Neither flag and no terminal: no key, and the output says what that means.
    let e = Env::init_with(&[]);
    assert!(e.recovery_key.is_none());
    assert!(!e.enabled());
}

#[test]
fn enable_shows_the_code_and_turns_the_key_on() {
    let e = Env::init();
    assert!(!e.enabled());
    let out = e.ok(&["recovery-key", "enable", "--saved"]);
    assert!(labelled(&out, "Recovery Key: ").is_some_and(|c| c.starts_with("FLR1-")));
    assert!(e.enabled());
    // Already on: enable refuses and the vault is as it was.
    let before = e.vault_json();
    let again = e.run(&["recovery-key", "enable", "--saved"]);
    assert!(!again.status.success());
    assert!(text(&again.stderr).contains("already on"));
    assert_eq!(e.vault_json(), before);
}

#[test]
fn enable_with_wrong_credentials_or_no_confirmation_changes_nothing() {
    let e = Env::init();
    let before = e.vault_json();
    let wrong_pw = e.exec(
        &["recovery-key", "enable", "--saved"],
        "",
        "not-the-password",
        Some(&e.secret_key),
        &[],
    );
    assert!(!wrong_pw.status.success());
    let wrong_sk = e.exec(
        &["recovery-key", "enable", "--saved"],
        "",
        PW,
        Some("FL1-AAAAA-AAAAA-AAAAA-AAAAA-AAAAA-AAAAA-AAAAA-AAAAA-AAAAA"),
        &[],
    );
    assert!(!wrong_sk.status.success());
    // Without --saved a script cannot confirm the code, so nothing is written.
    let unconfirmed = e.run(&["recovery-key", "enable"]);
    assert!(!unconfirmed.status.success());
    assert!(text(&unconfirmed.stderr).contains("--saved"));
    assert_eq!(e.vault_json(), before);
    assert!(!e.enabled());
}

#[test]
fn a_kit_page_is_written_when_asked_and_never_over_an_existing_file() {
    let e = Env::init();
    let dir = TempDir::new().unwrap();
    let path = dir.path().join("recovery.pdf");
    let p = path.to_str().unwrap();
    e.ok(&["recovery-key", "enable", "--saved", "--kit", p]);
    assert!(fs::read(&path).unwrap().starts_with(b"%PDF"));
    // Replacing with the same path is refused before the vault changes.
    let before = e.vault_json();
    let again = e.run(&["recovery-key", "replace", "--saved", "--kit", p]);
    assert!(!again.status.success());
    assert!(text(&again.stderr).contains("already exists"));
    assert_eq!(e.vault_json(), before);
}

#[test]
fn replace_ends_the_old_code_and_disable_ends_them_all() {
    let e = Env::init();
    e.add("Kept");
    let old = e.enable();
    let new = {
        let out = e.ok(&["--json", "recovery-key", "replace", "--saved"]);
        let v: Value = serde_json::from_str(&out).unwrap();
        assert_eq!(v["replaced"], true);
        v["recovery_key"].as_str().unwrap().to_owned()
    };
    assert_ne!(old, new);

    // The old code opens nothing, and a failed attempt writes nothing.
    let before = e.vault_json();
    let out = e.forgot(&old, &[]);
    assert!(!out.status.success());
    assert!(
        text(&out.stderr).contains("does not open this vault"),
        "{}",
        text(&out.stderr)
    );
    assert_eq!(e.vault_json(), before);
    assert!(
        e.find(PW, &e.secret_key).status.success(),
        "credentials unchanged"
    );

    // Replace needs a key to replace.
    let off = Env::init();
    let r = off.run(&["recovery-key", "replace", "--saved"]);
    assert!(!r.status.success() && text(&r.stderr).contains("no Recovery Key to replace"));

    // Disable (asks nothing with --yes) and then no code works.
    e.ok(&["recovery-key", "disable", "--yes"]);
    assert!(!e.enabled());
    let after = e.forgot(&new, &[]);
    assert!(!after.status.success());
    assert!(text(&after.stderr).contains("no Recovery Key"));
    let again = e.run(&["recovery-key", "disable", "--yes"]);
    assert!(!again.status.success());
}

#[test]
fn disable_without_yes_asks_and_a_script_cannot_answer() {
    let e = Env::init();
    e.enable();
    let out = e.run(&["recovery-key", "disable"]);
    assert!(!out.status.success());
    assert!(e.enabled(), "still on");
}

#[test]
fn forgot_resets_the_password_and_the_secret_key_and_rotates_the_recovery_key() {
    let e = Env::init();
    e.add("Bank");
    e.add("Mail");
    let old_code = e.enable();
    let before = e.vault_json();

    let out = e.forgot(&old_code, &[]);
    assert!(out.status.success(), "{}", text(&out.stderr));
    let v: Value = serde_json::from_str(&text(&out.stdout)).unwrap();
    let new_sk = v["secret_key"].as_str().unwrap().to_owned();
    let new_code = v["recovery_key"].as_str().unwrap().to_owned();
    assert_ne!(new_sk, e.secret_key);
    assert_ne!(new_code, old_code);
    assert_ne!(e.vault_json(), before);
    // The outputs never carry the old code or the new password.
    let all = format!("{}{}", text(&out.stdout), text(&out.stderr));
    assert!(!all.contains(NEW_PW) && !all.contains(&old_code));

    // The old password and Secret Key open nothing; the new ones open everything.
    assert!(!e.find(PW, &e.secret_key).status.success());
    assert!(!e.find(NEW_PW, &e.secret_key).status.success());
    assert!(!e.find(PW, &new_sk).status.success());
    let found = e.find(NEW_PW, &new_sk);
    assert!(found.status.success(), "{}", text(&found.stderr));
    let listing = text(&found.stdout);
    assert!(listing.contains("Bank") && listing.contains("Mail"));

    // The code that was used is spent; the new one works.
    let spent = e.forgot(&old_code, &[]);
    assert!(!spent.status.success());
    let again = e.forgot(&new_code, &[]);
    assert!(again.status.success(), "{}", text(&again.stderr));
}

#[test]
fn forgot_can_keep_the_recovery_key_and_write_the_new_kits() {
    let e = Env::init();
    e.add("Bank");
    let code = e.enable();
    let dir = TempDir::new().unwrap();
    let kit = dir.path().join("kit.pdf");
    let rk = dir.path().join("rk.pdf");
    let out = e.forgot(
        &code,
        &["--keep-recovery-key", "--kit", kit.to_str().unwrap()],
    );
    assert!(out.status.success(), "{}", text(&out.stderr));
    let v: Value = serde_json::from_str(&text(&out.stdout)).unwrap();
    assert!(
        v.get("recovery_key").is_none(),
        "the old key stays: no new one is shown"
    );
    assert!(fs::read(&kit).unwrap().starts_with(b"%PDF"));
    // The same code still works.
    let out = e.forgot(&code, &["--recovery-kit", rk.to_str().unwrap()]);
    assert!(out.status.success(), "{}", text(&out.stderr));
    assert!(fs::read(&rk).unwrap().starts_with(b"%PDF"));
}

#[test]
fn forgot_with_a_wrong_key_a_weak_password_or_no_check_changes_nothing() {
    let e = Env::init();
    e.add("Bank");
    let code = e.enable();
    let other = Env::init_with(&["--recovery-key"]).recovery_key.unwrap();
    let before = e.vault_json();

    // Another vault's key, and text that is not a code at all.
    let wrong = e.forgot(&other, &[]);
    assert!(!wrong.status.success());
    assert!(text(&wrong.stderr).contains("does not open this vault"));
    let junk = e.forgot("FLR1-NOT-A-CODE", &[]);
    assert!(!junk.status.success());
    assert!(text(&junk.stderr).contains("not a valid Recovery Key"));

    // A short password is refused before anything is written.
    let weak = e.exec(
        &["forgot", "--saved"],
        "",
        "x",
        None,
        &[
            ("FIGLOCK_RECOVERY_KEY", &code),
            ("FIGLOCK_NEW_PASSWORD", "short"),
        ],
    );
    assert!(!weak.status.success());
    assert!(text(&weak.stderr).contains("at least 8"));

    // Without --saved a script cannot check the new Secret Key, so the vault is not written.
    let unchecked = e.exec(
        &["forgot"],
        "",
        "x",
        None,
        &[
            ("FIGLOCK_RECOVERY_KEY", &code),
            ("FIGLOCK_NEW_PASSWORD", NEW_PW),
        ],
    );
    assert!(!unchecked.status.success());
    assert!(text(&unchecked.stderr).contains("--saved"));

    assert_eq!(e.vault_json(), before);
    assert!(e.find(PW, &e.secret_key).status.success());
}

#[test]
fn forgot_on_a_vault_without_a_recovery_key_says_so() {
    let e = Env::init();
    let before = e.vault_json();
    let out = e.forgot("FLR1-AAAA", &[]);
    assert!(!out.status.success());
    assert!(text(&out.stderr).contains("no Recovery Key"));
    assert_eq!(e.vault_json(), before);
}

#[test]
fn a_new_device_can_reset_a_forgotten_password_from_the_vault_folder() {
    let e = Env::init();
    e.add("Bank");
    let code = e.enable();

    // A machine with nothing set up, pointed at the vault folder.
    let fresh = Env {
        home: TempDir::new().unwrap(),
        store: TempDir::new().unwrap(),
        secret_key: String::new(),
        recovery_key: None,
    };
    let store = e.store.path().to_str().unwrap().to_owned();
    let out = fresh.exec(
        &[
            "--json",
            "forgot",
            "--saved",
            "--store",
            &store,
            "--no-quick-unlock",
        ],
        "",
        "unused",
        None,
        &[
            ("FIGLOCK_RECOVERY_KEY", &code),
            ("FIGLOCK_NEW_PASSWORD", NEW_PW),
        ],
    );
    assert!(out.status.success(), "{}", text(&out.stderr));
    let v: Value = serde_json::from_str(&text(&out.stdout)).unwrap();
    let new_sk = v["secret_key"].as_str().unwrap();
    let found = fresh.find(NEW_PW, new_sk);
    assert!(found.status.success(), "{}", text(&found.stderr));
    assert!(text(&found.stdout).contains("Bank"));
    // The first machine's old credentials are now dead.
    assert!(!e.find(PW, &e.secret_key).status.success());
}
